-- bekup: least-privilege roles and database for an external PostgreSQL 15+
-- (generated by "bekup db roles-sql"; D-207, docs/installation/external-database.md).
--
-- Run it once as an account with CREATEROLE and CREATEDB (or the provider's
-- admin role: rds_superuser, cloudsqlsuperuser, azure_pg_admin), connected
-- to the maintenance database over TLS, for example:
--   psql -v ON_ERROR_STOP=1 --no-psqlrc -f bekup-roles.sql \
--     "host=<host> dbname=postgres user=<admin> sslmode=verify-full sslrootcert=<ca.pem>"
--
-- The script grants bekup_owner to the executing account only for its
-- duration (the last statement revokes it). If it stops with an error after
-- that GRANT, revoke the membership by hand as the same account:
--   REVOKE bekup_owner FROM CURRENT_USER;
--
\set ON_ERROR_STOP on
SET password_encryption = 'scram-sha-256';

CREATE ROLE bekup_owner WITH LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS INHERIT;
\echo 'Enter the password of bekup_owner twice (the content of its password file):'
\password bekup_owner
CREATE ROLE bekup_app WITH LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS NOINHERIT CONNECTION LIMIT 100;
\echo 'Enter the password of bekup_app twice (the content of its password file):'
\password bekup_app
GRANT bekup_owner TO CURRENT_USER;
CREATE DATABASE "bekup" WITH OWNER bekup_owner ENCODING 'UTF8' TEMPLATE template0;
REVOKE ALL ON DATABASE "bekup" FROM PUBLIC;
GRANT CONNECT ON DATABASE "bekup" TO bekup_app;
REVOKE bekup_owner FROM CURRENT_USER;

-- Next: put the role passwords into database.password_file and
-- database.owner_password_file, then run: bekup migrate check && bekup migrate up
